const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grafton = ee.Geometry.Point([152.93, -29.69]);
  const startDate = '2020-01-14';
  const endDate = '2020-01-23'; // exclusive end date

  // 2. Data Acquisition & Check
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterBounds(grafton)
    .filterDate(startDate, endDate);

  const imageCount = chirps.size().getInfo();
  console.log(`CHIRPS Images found: ${imageCount}`);

  if (imageCount === 0) {
    console.log("No data available for the specified period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Sum all daily precipitation
  const totalPrecip = chirps.select('precipitation').sum();

  // 4. Calculation - Get total rainfall in mm
  const stats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: grafton,
    scale: 5566,
    maxPixels: 1e9
  }).getInfo();

  const totalMm = stats.precipitation;

  // 5. Validation & Final Answer
  if (totalMm === null || totalMm === undefined || isNaN(totalMm)) {
    console.log("Calculation failed - invalid result");
    console.log("<answer>C3</answer>");
    return;
  }

  const totalInches = totalMm / 25.4;
  const threshold = 6.0;

  console.log(`Total rainfall: ${totalMm.toFixed(2)} mm (${totalInches.toFixed(2)} inches)`);
  console.log(`Threshold: ${threshold} inches (${(threshold * 25.4).toFixed(2)} mm)`);
  console.log(`Period: ${startDate} to ${endDate}`);

  if (totalInches > threshold) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
